import type * as React from 'react';

import { CHART_THEME } from '../utils/chart-theme';
import { cn } from '../../../../lib/utils';
import type { BaseChartProps } from '../types/chart-types';
import { type ChartConfig, ChartContainer } from '../../../ui/display/chart';
import { EmptyState } from '../../../ui/feedback/empty-state';
import MLChartLoading from '../../ml-chart-loading/component';

/**
 * Props for ChartWrapper component
 */
export interface ChartWrapperProps extends BaseChartProps {
  /** Chart configuration for colors and labels */
  config: ChartConfig;
  /** Chart content - must be a Recharts chart component */
  children: React.ReactElement;
}

/**
 * ChartWrapper Component
 *
 * Provides consistent loading, error, and empty states for all charts.
 * Automatically applies CHART_THEME height tokens and integrates with ChartContainer.
 *
 * @example
 * ```tsx
 * <ChartWrapper
 *   config={chartConfig}
 *   height="lg"
 *   loading={isLoading}
 *   error={error}
 *   empty={!data.length}
 * >
 *   <LineChart data={data}>...</LineChart>
 * </ChartWrapper>
 * ```
 */
export function ChartWrapper({
  children,
  config,
  height = 'lg',
  loading,
  error,
  empty,
  className,
}: ChartWrapperProps) {
  // Show loading state
  if (loading) {
    return <MLChartLoading variant="wave" chartHeight={height} />;
  }

  // Show error state
  if (error) {
    return <EmptyState variant="error" size="lg" />;
  }

  // Show empty state (no data)
  if (empty) {
    return <EmptyState variant="chart" size="lg" />;
  }

  // Resolve height class from CHART_THEME or use custom value
  const heightClass =
    typeof height === 'string' && height in CHART_THEME.heights
      ? CHART_THEME.heights[height as keyof typeof CHART_THEME.heights]
      : height;

  return (
    <ChartContainer config={config} className={cn(heightClass, 'w-full', className)}>
      {children}
    </ChartContainer>
  );
}

import type * as React from 'react';
import type { Payload } from 'recharts/types/component/DefaultTooltipContent';
import type { NameType, ValueType } from 'recharts/types/component/DefaultTooltipContent';
import type { TimeGranularity } from '../../../../types/date';
import type { UOM } from '../../../../types/uom';
import type { ChartFormattingAdapter } from '../types/chart-formatting';
import { defaultChartFormattingAdapter } from '../types/chart-formatting';

/**
 * Chart formatter functions
 */
export interface ChartFormatters {
  /** Format X-axis labels (dates/periods) */
  xAxisFormatter: (value: string | number) => string;
  /** Format Y-axis labels (values with units) */
  yAxisFormatter: (value: number) => string;
  /** Format tooltip labels (detailed dates) - for ChartTooltipContent labelFormatter prop */
  tooltipLabelFormatter: (
    value: NameType,
    payload: Payload<ValueType, NameType>[]
  ) => React.ReactNode;
  /** Format tooltip values (numbers with UOM) - for ChartTooltipContent formatter prop */
  tooltipValueFormatter: (
    value: ValueType,
    name: NameType,
    item: Payload<ValueType, NameType>,
    index: number,
    payload: Payload<ValueType, NameType>[]
  ) => React.ReactNode;
}

/**
 * Hook to get chart formatters based on time granularity and unit of measure
 *
 * @param timeGranularity - Time granularity for date formatting
 * @param uom - Unit of measure for value formatting
 * @param formattingAdapter - Optional adapter to override default formatting behavior
 * @returns Chart formatter functions
 */
export function useChartFormatter(
  timeGranularity?: TimeGranularity,
  _uom?: UOM,
  formattingAdapter?: Partial<ChartFormattingAdapter>
): ChartFormatters {
  const adapter: ChartFormattingAdapter = {
    ...defaultChartFormattingAdapter,
    ...formattingAdapter,
  };

  const xAxisFormatter = (value: string | number): string => {
    return adapter.xAxisFormatter(value, timeGranularity);
  };

  const yAxisFormatter = (value: number): string => {
    return adapter.yAxisFormatter(value);
  };

  const tooltipLabelFormatter = (
    value: NameType,
    payload: Payload<ValueType, NameType>[]
  ): React.ReactNode => {
    return adapter.tooltipLabelFormatter(value, payload, timeGranularity);
  };

  const tooltipValueFormatter = (
    value: ValueType,
    name: NameType,
    item: Payload<ValueType, NameType>,
    _index: number,
    _payload: Payload<ValueType, NameType>[]
  ): React.ReactNode => {
    return adapter.tooltipValueFormatter(value, name, item, _index, _payload);
  };

  return {
    xAxisFormatter,
    yAxisFormatter,
    tooltipLabelFormatter,
    tooltipValueFormatter,
  };
}

/**
 * Hook to get responsive chart height based on viewport
 * Automatically adjusts chart height for mobile, tablet, desktop
 *
 * @returns Current chart height class
 */
export function useChartResponsive(): 'sm' | 'md' | 'lg' {
  // Will be implemented with window resize listener
  // For now, returns default
  return 'lg';
}

export { CHART_THEME } from './utils/chart-theme';
export type { ChartHeight, ChartMarginPreset } from './utils/chart-theme';

// Types
export type {
  BaseChartProps,
  ChartAxisProps,
  ChartDataPoint,
  ChartMargin,
  ChartInteractionProps,
  ChartContainerProps,
} from './types/chart-types';

// Hooks
export { useChartFormatter, useChartResponsive } from './hooks/use-chart-formatter';
export type { ChartFormatters } from './hooks/use-chart-formatter';

// Base components
export { ChartWrapper } from './base/chart-wrapper';
export type { ChartWrapperProps } from './base/chart-wrapper';
export { ChartLegend, ChartLegendContent } from '../../ui';

// UI chart primitives
export { ChartContainer, ChartTooltip, ChartTooltipContent } from '../../ui/display/chart';
export type { ChartConfig } from '../../ui/display/chart';

// Re-export color system from shared-ui root
export {
  CHART_COLORS,
  CHART_PALETTE,
  CHART_SEMANTIC_COLORS,
  COLOR_MIGRATION_MAP,
  getChartColor,
  convertHslToOklch,
} from './utils/chart-colors';
export type {
  ChartColor,
  ChartPaletteColor,
  ChartSemanticColor,
} from './utils/chart-colors';

import type * as React from 'react';
import type { Payload, NameType, ValueType } from 'recharts/types/component/DefaultTooltipContent';
import { formatXAxisLabel } from '../utils/format-x-axis-label';
import { formatDetailedDate } from '../../../../utils/date-formatting';
import { formatCompact } from '../../../../utils/number-formatting';
import type { TimeGranularity } from '../../../../types/date';

export interface ChartFormattingAdapter {
  xAxisFormatter: (value: string | number, granularity?: TimeGranularity) => string;
  yAxisFormatter: (value: number) => string;
  tooltipLabelFormatter: (
    value: NameType,
    payload: Payload<ValueType, NameType>[],
    granularity?: TimeGranularity
  ) => React.ReactNode;
  tooltipValueFormatter: (
    value: ValueType,
    name: NameType,
    item: Payload<ValueType, NameType>,
    index: number,
    payload: Payload<ValueType, NameType>[]
  ) => React.ReactNode;
}

export const defaultChartFormattingAdapter: ChartFormattingAdapter = {
  xAxisFormatter: (value, granularity) =>
    granularity ? formatXAxisLabel(String(value), granularity) : String(value),

  yAxisFormatter: (value) => {
    if (!value && value !== 0) return '';
    return formatCompact(value, 1);
  },

  tooltipLabelFormatter: (value, payload, granularity) => {
    if (!granularity) return String(value);
    const timestamp = payload?.[0]?.payload?.timestamp ?? value;
    return formatDetailedDate(String(timestamp), granularity);
  },

  tooltipValueFormatter: (value, name, item, _index, _payload) => {
    const rawValue = Array.isArray(value) ? value[0] : value;
    const numericValue = rawValue == null ? 0 : Number(rawValue);
    const formattedValue = formatCompact(numericValue, 2);
    const color = item?.color || item?.payload?.fill || item?.stroke;

    return (
      <>
        <span className="text-muted-foreground" style={{ color }}>
          {name}:
        </span>
        <span className="pl-3 font-medium font-mono text-foreground tabular-nums">
          {formattedValue}
        </span>
      </>
    );
  },
};

import type * as React from 'react';
import type { UOM } from '../../../../types/uom';
import type { TimeGranularity } from '../../../../types/date';
import type { ChartHeight, ChartMarginPreset } from '../utils/chart-theme';

/**
 * Chart margin configuration
 * Compatible with Recharts margin prop
 */
export type ChartMargin = {
  top?: number;
  right?: number;
  bottom?: number;
  left?: number;
};

/**
 * Base props shared by all chart components
 */
export interface BaseChartProps {
  /** Chart height - semantic token or custom CSS class */
  height?: ChartHeight | string;
  /** Chart margin - preset or custom object */
  margin?: ChartMarginPreset | ChartMargin;
  /** Loading state */
  loading?: boolean;
  /** Error state */
  error?: Error | null;
  /** Empty state (no data) */
  empty?: boolean;
  /** Additional CSS classes */
  className?: string;
}

/**
 * Chart axis configuration props
 */
export interface ChartAxisProps {
  /** Time granularity for X-axis labels */
  timeGranularity?: TimeGranularity;
  /** Unit of measure for Y-axis labels */
  uom?: UOM;
  /** Show grid lines */
  showGrid?: boolean;
  /** Show X-axis */
  showXAxis?: boolean;
  /** Show Y-axis */
  showYAxis?: boolean;
  /** Custom X-axis tick formatter (overrides default timeGranularity formatting) */
  xAxisFormatter?: (value: string | number) => string;
  /** Custom Y-axis tick formatter (overrides default UOM formatting) */
  yAxisFormatter?: (value: number) => string;
}

/**
 * Generic chart data point
 * Flexible structure for various chart types
 */
export interface ChartDataPoint {
  [key: string]: string | number | Date | null | undefined;
}

/**
 * Common chart interaction props
 */
export interface ChartInteractionProps {
  /** Show tooltip on hover */
  showTooltip?: boolean;
  /** Show legend */
  showLegend?: boolean;
  /** Enable brush for zooming */
  showBrush?: boolean;
  /** Custom tooltip formatter */
  tooltipFormatter?: (value: any, name: string) => React.ReactNode;
  /** Custom label formatter (receives string | number from Recharts tooltip) */
  labelFormatter?: (label: string | number, payload?: any) => string;
}

/**
 * Chart container props
 * Combines all common props
 */
export interface ChartContainerProps extends BaseChartProps, ChartAxisProps, ChartInteractionProps {
  /** Chart data */
  data: ChartDataPoint[];
  /** Chart configuration for colors/labels */
  config: Record<string, { label?: string; color?: string }>;
}

export const CHART_COLORS = {
  // Semantic names (recommended)
  PRIMARY: 'oklch(0.6242 0.1822 259.6956)',
  SECONDARY: 'oklch(0.6500 0.1800 145.0000)',
  TERTIARY: 'oklch(0.7200 0.1900 65.0000)',
  QUATERNARY: 'oklch(0.6200 0.2200 25.0000)',
  ACCENT: 'oklch(0.5464 0.2096 262.9482)',
  MUTED: 'oklch(0.9687 0.0030 264.5400)',

  // Explicit color names (aliases for clarity)
  BLUE: 'oklch(0.6242 0.1822 259.6956)',
  GREEN: 'oklch(0.6500 0.1800 145.0000)',
  ORANGE: 'oklch(0.7200 0.1900 65.0000)',
